package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.NodePointer;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.NamespaceResolver;
import org.apache.commons.jxpath.ri.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for NamespaceResolver#getPrefix
 */
public class NamespaceResolver_getPrefix_TriageGen1Test {

    private NamespaceResolver resolver;

    @Before
    public void setUp() {
        resolver = new NamespaceResolver();
    }

    @Test
    public void testGetPrefix_EmptyInitialState() {
        // Test when reverseMap is null and pointer/iterator is null
        // This covers the branch where ni == null
        assertNull(resolver.getPrefix("http://test.com"));
    }

    @Test
    public void testGetPrefix_WithNamespaceMapAndPointer() {
        // Mocking internal dependencies via reflection or setup if possible.
        // Since we cannot easily inject into private fields without reflection, 
        // we use the public API to populate the state.

        // 1. Test registerNamespace (populates namespaceMap)
        resolver.registerNamespace("p1", "http://uri1.com");
        resolver.registerNamespace("p2", "http://uri2.com");

        // 2. Mocking the Pointer and NodeIterator behavior
        // We need to simulate the pointer.namespaceIterator() logic
        Pointer mockPointer = mock(Pointer.class);
        NodeIterator mockIterator = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);

        when(mockPointer.namespaceIterator()).thenReturn(mockIterator);
        // Simulate one iteration
        when(mockIterator.setPosition(1)).thenReturn(true);
        when(mockIterator.getNodePointer()).thenReturn(mockNodePointer);
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://uri3.com");
        when(mockNodePointer.getName()).thenReturn(new org.apache.commons.jxpath.Name("p3"));
        // Simulate end of iteration
        when(mockIterator.setPosition(2)).thenReturn(false);

        // Use reflection to set the private pointer field if necessary, 
        // but here we assume the environment allows setting the context.
        // For the sake of a pure unit test, we rely on the class's ability to accept a pointer.
        // Note: setNamespaceContextPointer is a public method.

        // We need to bypass the fact that we can't easily mock the internal 'pointer' field 
        // if it's not accessible, but the provided signature suggests we can interact with it.
        // Since we cannot access private fields directly in standard JUnit without reflection:

        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(resolver, mockPointer);
        } catch (Exception e) {
            fail("Failed to set private pointer field via reflection: " + e.getMessage());
        }

        // Execute: This triggers the reverseMap initialization logic
        // It should combine namespaceMap (p1, p2) and iterator (p3)
        assertEquals("p1", resolver.getPrefix("http://uri1.com"));
        assertEquals("p2", resolver.getPrefix("http://uri2.com"));
        assertEquals("p3", resolver.getPrefix("http://uri3.com"));
    }

    @Test
    public void testGetPrefix_WithEmptyPrefixInIterator() {
        // Test the branch: if (!"".equals(prefix))
        Pointer mockPointer = mock(Pointer.class);
        NodeIterator mockIterator = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);

        when(mockPointer.namespaceIterator()).thenReturn(mockIterator);
        when(mockIterator.setPosition(1)).thenReturn(true);
        when(mockIterator.getNodePointer()).thenReturn(mockNodePointer);
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://empty.com");
        when(mockNodePointer.getName()).thenReturn(new org.apache.commons.jxpath.Name("")); // Empty prefix
        when(mockIterator.setPosition(2)).thenReturn(false);

        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(resolver, mockPointer);
        } catch (Exception e) {
            fail(e.getMessage());
        }

        // The empty prefix should not be added to reverseMap
        assertNull(resolver.getPrefix("http://empty.com"));
    }

    @Test
    public void testGetPrefix_ParentDelegation() {
        // Test the branch: if (prefix == null && parent != null)
        NamespaceResolver parentResolver = new NamespaceResolver();
        parentResolver.registerNamespace("parentPrefix", "http://parent.com");

        // Create child resolver with parent
        NamespaceResolver childResolver = new NamespaceResolver(parentResolver);

        // We need to trigger reverseMap initialization in child to avoid it being null 
        // but we want the child's reverseMap to NOT contain the URI.
        // We can do this by providing a pointer that returns nothing.
        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(childResolver, mock(Pointer.class));
        } catch (Exception e) {
            fail(e.getMessage());
        }

        // Child doesn't have it, should ask parent
        assertEquals("parentPrefix", childResolver.getPrefix("http://parent.com"));
    }

    @Test
    public void testGetPrefix_NotFoundInParent() {
        // Test the branch: prefix is null and parent is not null, but parent returns null
        NamespaceResolver parentResolver = new NamespaceResolver();
        NamespaceResolver childResolver = new NamespaceResolver(parentResolver);

        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(childResolver, mock(Pointer.class));
        } catch (Exception e) {
            fail(e.getMessage());
        }

        assertNull(childResolver.getPrefix("http://nonexistent.com"));
    }

    @Test
    public void testGetPrefix_AlreadyInitialized() {
        // Verify that if reverseMap is already non-null, it doesn't re-run the initialization logic
        resolver.registerNamespace("p", "http://p.com");

        // Force initialization
        resolver.getPrefix("http://p.com");

        // Mock a new pointer that would return something different if re-initialized
        Pointer mockPointer = mock(Pointer.class);
        NodeIterator mockIterator = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);
        when(mockPointer.namespaceIterator()).thenReturn(mockIterator);
        when(mockIterator.setPosition(1)).thenReturn(true);
        when(mockIterator.getNodePointer()).thenReturn(mockNodePointer);
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://different.com");
        when(mockNodePointer.getName()).thenReturn(new org.apache.commons.jxpath.Name("different"));
        when(mockIterator.setPosition(2)).thenReturn(false);

        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(resolver, mockPointer);
        } catch (Exception e) {
            fail(e.getMessage());
        }

        // If it didn't re-initialize, "http://different.com" will be null
        assertNull(resolver.getPrefix("http://different.com"));
        // "http://p.com" should still work
        assertEquals("p", resolver.getPrefix("http://p.com"));
    }
}
